mapper.select:
SELECT COUNT(*)
  FROM SANCTION_IMPACT I
  JOIN SANCTION S ON S.SNC_SN = I.SNC_SN
 WHERE I.SNC_SN != #{sanctionSn}
   AND I.SNC_IMP_REF_TYPE_CD = #{referenceTypeCode}
   AND I.SNC_IMP_REF_SN = #{referenceSn}
   AND I.SNC_IMP_STATUS_CD IN ('ACTIVE', 'RELEASE_PENDING')
   AND S.SNC_START_DT <= CURRENT_TIMESTAMP
   AND (S.SNC_END_DT IS NULL OR S.SNC_END_DT > CURRENT_TIMESTAMP)
